/* ---------- persistent settings / state (store.c) ---------- */
typedef struct {
    float hunger;          /* 0..100 */
    float dirt;            /* 0..100 */
    int64_t saved_at;      /* epoch seconds of last save, 0 = unknown */
    uint8_t face;          /* 0 = fish tank, 1 = minimal */
    uint8_t brightness;    /* 10..100 */
    uint8_t volume;        /* 0..100 */
    bool aod;              /* raise-to-wake */
    bool dnd;
    bool mute;
    bool power_save;
    char ssid[33];
    char pass[65];
    int16_t tz_min;        /* offset from UTC in minutes, e.g. 480 */
    uint16_t pr_kg10[5];   /* personal record per lift, kg*10 */
    uint32_t total_kg;     /* lifetime training volume */
    uint16_t workouts;
    uint8_t screen_timeout; /* seconds until the screen turns off, 0 = never */
    float lat, lon;         /* weather location */
    uint32_t steps;         /* today's steps */
    uint16_t step_day;      /* day-of-year the steps belong to */
    uint32_t step_goal;
    uint8_t alarm_on, alarm_h, alarm_m;
    char page_url[100];     /* phone settings page, for the pairing QR code */
    char light_key[64];     /* device key for the office light (Supabase device_set_light) */
    uint8_t remind_sit, remind_water;
    uint16_t game_best;
    /* office light by the user's mr-tracker account (light_set(p_person_id, p_pin)); the phone
     * checks the PIN with login_by_email before sending, so a wrong PIN is never stored */
    char light_person[40];  /* person uuid, "" = not signed in */
    char light_pin[33];
    char radio_url[128];    /* custom station from the phone page ("" = none) */
    uint8_t radio_station;  /* last station played */
    /* 小智 (xiaozhi.me) voice assistant */
    char xz_ota[128];       /* OTA / config URL, "" = the official server */
    char xz_url[128];       /* websocket URL the server gave us */
    char xz_token[200];
    char xz_uuid[40];       /* our Client-Id, made once */
    uint16_t pair_code;     /* kept, so the phone page / Android app needn't re-enter it */
    uint8_t notif_on;       /* keep Bluetooth on for the Android notification app */
    uint8_t tap_buzz;       /* vibrate on button taps (off by default: the click sound is enough) */
} settings_t;

typedef struct { bool ok; float temp, tmax, tmin; int code, hum; char upd[8]; } weather_t;
